// Test stackalloc with native-sized integers
Span<nint> signedSpan = stackalloc nint[4];
signedSpan[0] = 10;
signedSpan[1] = 20;
signedSpan[2] = 30;
signedSpan[3] = nint.MaxValue;

Console.WriteLine($"Span<nint> length: {signedSpan.Length}");
for (int i = 0; i < signedSpan.Length; i++)
    Console.WriteLine($"  [{i}] = {signedSpan[i]}");

Span<nuint> unsignedSpan = stackalloc nuint[3];
unsignedSpan[0] = 100;
unsignedSpan[1] = nuint.MaxValue;
unsignedSpan[2] = (nuint)IntPtr.Size;

Console.WriteLine($"\nSpan<nuint> length: {unsignedSpan.Length}");
for (int i = 0; i < unsignedSpan.Length; i++)
    Console.WriteLine($"  [{i}] = {unsignedSpan[i]}");

Console.WriteLine($"\nnint size: {sizeof(nint)} bytes");
Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");

